package com.thealgorithms.others;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import org.junit.jupiter.api.Test;

public class MiniMaxAlgorithmBugTest {

    @Test
    public void testSetScoresWithInvalidLength() {
        MiniMaxAlgorithm miniMax = new MiniMaxAlgorithm();
        int[] originalScores = miniMax.getScores();
        int[] invalidScores = {10, 20, 30};
        miniMax.setScores(invalidScores);
        assertArrayEquals(originalScores, miniMax.getScores());
    }
}
